mapper.select:
select id, order_no, user_id, sku, product_type, amount, amount_cent, state, out_trade_no,
       paid_at, granted_at, closed_at, refunded_cent, refunded_at, create_time, update_time
from pay_order
where order_no = #{orderNo}
  and user_id = #{userId}

mapper.update:
update pay_order
set state = 'paid', out_trade_no = #{outTradeNo}, paid_at = now(), update_time = now()
where order_no = #{orderNo}
  and user_id = #{userId}
  and state = 'created'

update pay_order
set state = 'granted', granted_at = now(), update_time = now()
where order_no = #{orderNo}
  and user_id = #{userId}
  and state in ('paid', 'granted')

update pay_order
set state = 'closed', closed_at = now(), update_time = now()
where order_no = #{orderNo}
  and user_id = #{userId}
  and state = 'created'

update pay_order
set state = 'refunded', refunded_cent = refunded_cent + #{refundedCent}, refunded_at = now(), update_time = now()
where order_no = #{orderNo}
  and user_id = #{userId}
  and state in ('paid', 'granted')

mapper.select:
select id, order_no, user_id, sku, product_type, amount, amount_cent, state, out_trade_no,
       paid_at, granted_at, closed_at, refunded_cent, refunded_at, create_time, update_time
from pay_order
where state = #{state}
order by id desc
limit #{limit}

select id, run_id, order_no, user_id, order_state, order_amount, ledger_amount, refunded_cent, reason, state, create_time
from pay_reconcile_diff

    and user_id = #{userId}

order by id desc
limit #{limit}

select id, out_trade_no, order_no, user_id, notify_seq, raw, result, create_time
from pay_callback_log
where order_no = #{orderNo}
order by id desc
limit #{limit}
